for rec in records.sudo():
    employee = rec.x_employee_id.sudo() if rec.x_employee_id else False

    if rec.x_state in ('returned', 'damaged', 'cancelled', 'superseded'):
        action = toast('No change', 'This custody item is already returned, damaged, cancelled, or superseded.', 'warning', False, reload_item(rec))
        continue

    event_on = datetime.date.today()
    damage_condition = rec.x_condition_on_return or 'Damaged'
    note_line = 'Custody item marked damaged on %s by %s. Repair/recovery/manual decision details should be recorded if required.' % (event_on, env.user.display_name)

    rec.write({
        'x_state': 'damaged',
        'x_condition_on_return': damage_condition,
        'x_clearance_required': True,
        'x_clearance_status': 'blocked',
        'x_responsible_user_id': env.user.id,
        'x_clearance_notes': ((rec.x_clearance_notes or '') + '\n' + note_line).strip(),
        'x_notes': ((rec.x_notes or '') + '\n' + note_line).strip(),
    })

    if employee:
        employee.message_post(
            body='تم تسجيل العهدة كتـالفة: %s' % (rec.x_name or rec.x_document_reference or rec.id),
            subtype_xmlid='mail.mt_note',
        )

    action = toast('Custody damaged', 'Custody item was marked damaged and clearance status was set to blocked.', 'warning', False, reload_item(rec))
    break

